buggy.from_man_exp_non_integral_behavior:
from mpmath import from_man_exp, mp

# Test 1: Try to create a number with non-integral mantissa (1.5)
try:
    result = from_man_exp(1.5, 0)
    probe('non_integral_mantissa_accepted', 1)
except TypeError as e:
    probe('non_integral_mantissa_accepted', 0)
except Exception as e:
    probe('non_integral_mantissa_accepted', -1)

# Test 2: Try with float mantissa
try:
    result = from_man_exp(2.5, 10)
    probe('float_mantissa_accepted', 1)
except TypeError as e:
    probe('float_mantissa_accepted', 0)
except Exception as e:
    probe('float_mantissa_accepted', -1)

# Test 3: Check if integral mantissa still works
try:
    result = from_man_exp(1, 0)
    probe('integral_mantissa_works', 1)
except Exception as e:
    probe('integral_mantissa_works', 0)

